// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CustomerBranch) predicate.CustomerBranch {
	return predicate.CustomerBranch(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CustomerBranch) predicate.CustomerBranch {
	return predicate.CustomerBranch(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CustomerBranch) predicate.CustomerBranch {
	return predicate.CustomerBranch(sql.NotPredicates(p))
}
